SELECT PROJECT_ID AS project_id,PROJECT_CODE AS project_code,PROJECT_NAME AS project_name,TIMEZONE AS timezone,DEFAULT_POOL AS default_pool,MAX_RUNNING_TASKS AS max_running_tasks,ACTIVE_FLAG AS active_flag,ENVIRONMENT_TYPE AS environment_type,ENVIRONMENT_NAME AS environment_name,GOVERNANCE AS governance,SCHEMA_CHECK_SCHEDULE AS schema_check_schedule,SCHEMA_CHECK_ON_DEMAND AS schema_check_on_demand FROM CFG_PROJECTS ORDER BY PROJECT_CODE
